// Parse router response and determine which agent to call
const response = $input.first().json;
const text = response.choices?.[0]?.message?.content || response.text || '{}';
const incoming = $('Build Router Context').first().json;

let routing = {};
try {
  routing = JSON.parse(text.replace(/```json?/g, '').replace(/```/g, '').trim());
} catch(e) {
  routing = {
    intent: 'greeting',
    confidence: 0.5,
    agent: 'sales_agent',
    urgency: 'medium',
    needs_human: false,
    reasoning: 'Failed to parse, defaulting to sales'
  };
}

// Force human escalation if confidence too low
if (routing.confidence < 0.6) {
  routing.needs_human = true;
  routing.agent = 'human_escalation';
}

return [{
  json: {
    ...incoming,
    intent: routing.intent,
    confidence: routing.confidence,
    target_agent: routing.agent,
    urgency: routing.urgency,
    needs_human: routing.needs_human,
    routing_reasoning: routing.reasoning
  }
}];

// Human escalation - notify admin and send holding message
const data = $input.first().json;

return [{
  json: {
    ...data,
    ai_response: `${data.name}, entendo! Vou passar voce para nossa equipe agora mesmo. Alguem vai te responder em alguns minutos. Obrigada pela paciencia! \n\n- Ana, BR Academy`,
    metadata_line: '[STAGE:' + data.stage + '|FOLLOWUP:1|SCORE_DELTA:+0]',
    notify_admin: true,
    escalation_reason: data.routing_reasoning || 'Low confidence or explicit request'
  }
}];

// Redirect unrelated messages
const data = $input.first().json;

return [{
  json: {
    ...data,
    ai_response: `Oi ${data.name}! Aqui e a Ana da BR Academy. Nosso foco e treinamento de Bar Staff para voce trabalhar em pubs e bares aqui na Irlanda!\n\nPosso te ajudar com:\n- Informacoes sobre o curso\n- Datas e horarios\n- Precos e formas de pagamento\n- Duvidas sobre trabalhar em bares\n\nEm que posso te ajudar?`,
    metadata_line: '[STAGE:' + data.stage + '|FOLLOWUP:24|SCORE_DELTA:-5]'
  }
}];

// Merge all agent responses and extract metadata
const input = $input.first().json;

let fullResponse = '';
let metadata = '';

// Check if response comes from OpenAI or code node
if (input.choices) {
  fullResponse = input.choices[0]?.message?.content || '';
} else if (input.ai_response) {
  fullResponse = input.ai_response;
  metadata = input.metadata_line || '';
}

// Extract metadata line [STAGE:x|FOLLOWUP:y|SCORE_DELTA:z]
if (!metadata) {
  const metaMatch = fullResponse.match(/\[STAGE:(\w+)\|FOLLOWUP:(\d+)\|SCORE_DELTA:([+-]?\d+)\]/);
  if (metaMatch) {
    metadata = metaMatch[0];
    fullResponse = fullResponse.replace(metaMatch[0], '').trim();
  }
}

let stage = '';
let followUpHours = 24;
let scoreDelta = 0;

const parsed = metadata.match(/STAGE:(\w+)\|FOLLOWUP:(\d+)\|SCORE_DELTA:([+-]?\d+)/);
if (parsed) {
  stage = parsed[1];
  followUpHours = parseInt(parsed[2]);
  scoreDelta = parseInt(parsed[3]);
}

// Get original context
const context = $('Build Router Context').first().json;

return [{
  json: {
    lead_id: context.lead_id,
    phone: context.phone,
    name: context.name,
    response_message: fullResponse,
    suggested_stage: stage || context.stage,
    follow_up_hours: followUpHours,
    score_delta: scoreDelta,
    current_score: context.score,
    new_score: Math.min(100, Math.max(0, (parseInt(context.score) || 0) + scoreDelta)),
    target_agent: context.target_agent,
    intent: context.intent,
    notify_admin: input.notify_admin || false,
    escalation_reason: input.escalation_reason || ''
  }
}];

